"""Golden file location and loader (files from make_goldens.py, never regenerated by tests)."""

import os
from functools import lru_cache
from pathlib import Path

import pytest
import torch

GOLDEN_DIR = Path(os.environ.get("TAFSUT_GOLDENS", "/home/andy/bringup/goldens/tafsut"))


@lru_cache(maxsize=4)
def load_golden(name: str) -> dict:
    path = GOLDEN_DIR / f"{name}.pt"
    if not path.is_file():
        pytest.skip(f"golden {path} missing (make_goldens.py)")
    return torch.load(path, weights_only=False)
